settings.script:
# Changes the password of the connection account itself. passwd asks
# for the current password first, unless the account is root.
passwd
@case (?i)\b(current|old|existing)\b[^:\n]*password:
<OLDPASS>
@expect assword:
@case (?i)\bnew\b[^:\n]*password:
@end
<NEWPASS>
@expect assword:
<NEWPASS>
@regex (?i)(success|(?<!not |un)(updated|changed)\b|\bdone\b)

# Changes the password of the connection account itself, then that of its
# login keychain, which passwd leaves as it was. passwd asks for the current
# password first, unless the account is root.
passwd
@case (?i)\b(current|old|existing)\b[^:\n]*password:
<OLDPASS>
@expect assword:
@case (?i)\bnew\b[^:\n]*password:
@end
<NEWPASS>
@expect assword:
<NEWPASS>
@case (?m)^passwd: 
@fail passwd did not change the password.
@case keychain password
@regex (?m)^#{10,}\s*$
@end
security set-keychain-password ~/Library/Keychains/login.keychain-db
@expect Old Password:
<OLDPASS>
@expect New Password:
<NEWPASS>
@expect Retype New Password:
<NEWPASS>
@case (?m)^security: 
@fail The login keychain password was not changed.
@case [%$#>] $
@end

# Changes the password of the connection account itself.
@timeout 20
@expect >
net user <USER> *
@expect password
<NEWPASS>
@expect password
<NEWPASS>
@expect successfully
